"""Weekly timesheet lines built from a list of shifts."""

import typing

import hourglass.models

MINUTES_PER_HOUR = 60


def timesheet_lines(
    shifts: typing.Iterable[hourglass.models.Shift],
) -> typing.List[str]:
    """One line per worker: name, shift count, hours (busiest first)."""
    counts = {}
    minutes = {}
    for shift in shifts:
        name = shift.worker.strip()
        if not name:
            raise ValueError("shift has a blank worker name")
        counts[name] = counts.get(name, 0) + 1
        total = minutes.get(name, 0) + shift.span.minutes
        minutes[name] = total
    if not counts:
        raise ValueError("no shifts given")
    names = sorted(
        counts, key=lambda n: (-minutes[n], n)
    )
    lines = []
    for name in names:
        hours = minutes[name] / MINUTES_PER_HOUR
        lines.append(f"{name}: {counts[name]} shifts, {hours:.1f} h")
    return lines
