cat > tests/test_timesheet.py <<'EOF'
import unittest

import hourglass.models
import hourglass.timesheet


def make_shift(worker, start, end):
    span = hourglass.models.Span(start, end)
    return hourglass.models.Shift(worker, "mon", span)


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        """The worker with the most hours is listed first."""
        lines = hourglass.timesheet.timesheet_lines(
            [make_shift("Ana", 0, 60), make_shift("Bo", 0, 120)]
        )
        self.assertTrue(lines[0].startswith("Bo"))

    def test_line_format(self):
        """A line shows name, shift count and one-decimal hours."""
        lines = hourglass.timesheet.timesheet_lines(
            [make_shift("Ana", 0, 90), make_shift("Ana", 120, 180)]
        )
        self.assertTrue(lines == ["Ana: 2 shifts, 2.5 h"])

    def test_empty(self):
        """An empty list of shifts raises."""
        with self.assertRaises(ValueError):
            hourglass.timesheet.timesheet_lines([])

    def test_blank_worker(self):
        """A blank worker name raises."""
        with self.assertRaises(ValueError):
            hourglass.timesheet.timesheet_lines(
                [make_shift("  ", 0, 60)]
            )


if __name__ == "__main__":
    unittest.main()
